<?php require __DIR__.'/partials/header.php';$type=$_GET['tipo']??'';$season=$_GET['stagione']??'';$sql='SELECT * FROM market_moves WHERE 1';$a=[];if($type!==''){$sql.=' AND move_type=?';$a[]=$type;}if($season!==''){$sql.=' AND season=?';$a[]=$season;}$sql.=' ORDER BY move_date DESC';$st=$db->prepare($sql);$st->execute($a);$rows=$st->fetchAll();?><section class="page-hero"><div class="wrap"><span class="eyebrow">ROSTER UPDATE</span><h1>IL <em>MERCATO</em></h1><p>Movimenti inventati per il prototipo, non comunicati ufficiali.</p></div></section><section class="wrap section"><form class="filters"><select name="tipo"><option value="">Tutte le operazioni</option><?php foreach(['Acquisto','Conferma','Cessione','Prestito'] as $t): ?><option <?= $type===$t?'selected':'' ?>><?= e($t) ?></option><?php endforeach; ?></select><input name="stagione" placeholder="Stagione (es. 2026/27)" value="<?= e($season) ?>"><button class="btn btn-red">Filtra</button></form><div class="match-list"><?php foreach($rows as $m): ?><article class="schedule-card"><div class="opponent-mark">↗</div><div class="schedule-main"><span class="eyebrow"><?= e($m['move_type']) ?> · DEMO</span><h3><?= e($m['player_name']) ?></h3><p><?= e($m['description']) ?></p><small><?= e($m['origin_destination']) ?></small></div><div class="schedule-date"><small><?= e(date('d/m/Y',strtotime($m['move_date']))) ?></small></div></article><?php endforeach; ?></div><?php if(!$rows): ?><p class="empty">Nessun movimento presente.</p><?php endif; ?></section><?php require __DIR__.'/partials/footer.php'; ?>